head.b:skin:
/* =========================================================
   NORTHSTAR — Blogger editorial magazine template
   Colors, spacing and breakpoints are centralized below.
   ========================================================= */
:root {
  --brand:#123768; --brand-deep:#0d2850; --accent:#ffc928;
  --ink:#202733; --muted:#737d8b; --line:#e7eaf0;
  --surface:#fff; --soft:#f4f6f9; --footer:#172238;
  --container:1260px; --radius:5px; --shadow:0 12px 35px rgba(16,35,64,.12);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:90px}
body{margin:0;background:var(--surface);color:var(--ink);font-family:Inter,Arial,sans-serif;font-size:14px;line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto}
a{color:inherit;text-decoration:none}
a:hover{color:var(--brand)}
button,input{font:inherit}
button,a{ -webkit-tap-highlight-color:transparent}
button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #f0b900;outline-offset:3px}
.skip-link{position:absolute;left:-9999px;top:10px;background:#fff;padding:10px;z-index:9999}
.skip-link:focus{left:10px}
.wrap{width:min(var(--container),calc(100% - 40px));margin-inline:auto}
.site-header{position:sticky;top:0;z-index:1000;background:var(--brand);color:#fff;box-shadow:0 2px 12px rgba(0,0,0,.08);transition:box-shadow .25s,background .25s}
.site-header.is-scrolled{box-shadow:0 8px 24px rgba(4,20,44,.22);background:var(--brand-deep)}
.header-inner{min-height:66px;display:flex;align-items:center;gap:26px}
.brand{display:flex;align-items:center;gap:9px;flex-shrink:0;color:#fff;font-weight:800;font-size:22px;letter-spacing:-.8px}
.brand-mark{display:grid;place-items:center;width:29px;height:29px;border-radius:50%;background:#fff;color:var(--brand);font-size:18px;line-height:1}
.brand-name span{color:var(--accent)}
.brand:hover{color:#fff}
.primary-nav{display:flex;align-items:center;justify-content:flex-end;gap:clamp(12px,2vw,27px);margin-left:auto}
.primary-nav a{font-size:12px;font-weight:600;color:#f4f7fc;white-space:nowrap;transition:color .2s}
.primary-nav a:hover{color:var(--accent)}
.coop-link{background:var(--accent);color:#1d2736!important;padding:7px 15px;border-radius:18px;font-weight:700!important}
.coop-link:hover{background:#ffda58}
.header-actions{display:flex;align-items:center;gap:10px}
.icon-button,.menu-toggle{border:0;background:transparent;color:#fff;display:grid;place-items:center;width:36px;height:36px;cursor:pointer;border-radius:50%}
.icon-button:hover,.menu-toggle:hover{background:rgba(255,255,255,.12)}
.icon-button svg,.menu-toggle svg{width:19px;height:19px}
.menu-toggle{display:none}
.search-panel{display:none;background:#fff;color:var(--ink);border-top:1px solid rgba(255,255,255,.1);padding:14px 0}
.search-panel.is-open{display:block;animation:dropIn .22s ease both}
.search-form{display:flex;max-width:680px;margin:auto;padding:0 20px}
.search-form input{min-width:0;flex:1;border:1px solid var(--line);padding:12px 14px;border-radius:4px 0 0 4px}
.search-form button{border:0;background:var(--accent);padding:0 20px;font-weight:700;border-radius:0 4px 4px 0;cursor:pointer}
.page-shell{padding:30px 0 42px}
.home-layout{display:grid;grid-template-columns:minmax(0, 2.05fr) minmax(270px, .95fr);gap:42px;align-items:start}
.section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 17px}
.section-heading h2,.section-heading h1{font-size:19px;line-height:1.3;margin:0;font-weight:800;letter-spacing:-.45px}
.heading-star{color:#f0b91a;font-size:17px}
.section-link{border:1px solid #9baabd;color:#49627f;font-size:11px;padding:4px 9px;border-radius:2px;white-space:nowrap}
.section-link:hover{background:var(--brand);border-color:var(--brand);color:#fff}
.featured-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.95fr);gap:22px;padding-bottom:27px;border-bottom:1px solid var(--line)}
.featured-primary .thumb{display:block;position:relative;overflow:hidden;background:#e9edf3;aspect-ratio:16/9}
.thumb img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .55s cubic-bezier(.2,.7,.2,1)}
.article-card:hover .thumb img,.featured-primary:hover .thumb img,.mini-article:hover img{transform:scale(1.035)}
.category-badge{display:inline-block;background:#202a3b;color:#fff;font-size:10px;line-height:1.4;font-weight:700;text-transform:uppercase;letter-spacing:.3px;padding:4px 7px}
.featured-primary .category-badge{margin-top:13px}
.article-title{font-size:18px;line-height:1.32;letter-spacing:-.35px;font-weight:800;margin:7px 0 8px}
.article-title a:hover,.mini-article a:hover{color:#d64b43}
.post-meta{font-size:10px;color:var(--muted);margin-top:7px}
.post-excerpt{font-size:12px;color:#596372;line-height:1.65;margin:8px 0 0}
.featured-list{display:flex;flex-direction:column;gap:15px}
.mini-article{display:grid;grid-template-columns:100px minmax(0,1fr);gap:12px;align-items:start;min-width:0}
.mini-article .mini-thumb{display:block;overflow:hidden;background:var(--soft);aspect-ratio:4/3}
.mini-article img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .4s}
.mini-article h3{font-size:12px;line-height:1.38;font-weight:800;margin:0}
.mini-article .post-meta{margin-top:5px}
.featured-secondary{margin-top:23px;padding-top:4px}
.featured-secondary .section-heading{margin-bottom:13px}
.featured-secondary-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.featured-secondary .mini-article{grid-template-columns:96px minmax(0,1fr);margin-bottom:14px}
.business-sidebar{min-width:0}
.sidebar-list{display:flex;flex-direction:column;gap:15px}
.sidebar-list .mini-article{grid-template-columns:94px minmax(0,1fr);gap:12px}
.sidebar-list .mini-article h3{font-size:12px}
.category-row{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:34px;padding-top:23px;border-top:1px solid var(--line)}
.category-block{min-width:0}
.category-block .section-heading h2{font-size:18px}
.category-list{display:flex;flex-direction:column;gap:14px}
.category-list .mini-article{grid-template-columns:96px minmax(0,1fr);gap:11px}
.category-list .mini-article h3{font-size:12px}
.latest-section{margin-top:34px;padding-top:24px;border-top:1px solid var(--line)}
.latest-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:27px 24px}
.article-card{min-width:0}
.article-card .thumb{position:relative;display:block;overflow:hidden;background:var(--soft);aspect-ratio:16/9}
.article-card .thumb .category-badge{position:absolute;top:8px;left:8px}
.article-card .article-title{font-size:15px;margin:9px 0 5px;line-height:1.38}
.article-card .post-excerpt{font-size:11px;margin-top:7px}
.load-more-wrap{text-align:center;padding:28px 0 0}
.load-more{border:0;background:var(--brand);color:#fff;padding:11px 23px;font-size:12px;font-weight:700;border-radius:3px;cursor:pointer;box-shadow:0 3px 8px rgba(18,55,104,.18);transition:transform .2s,background .2s}
.load-more:hover{background:var(--brand-deep);transform:translateY(-2px)}
.load-more[disabled]{opacity:.55;cursor:wait;transform:none}
.page-content{min-width:0}
.post-page{max-width:850px;margin-inline:auto}
.post-page h1{font-size:clamp(28px,4vw,42px);line-height:1.16;letter-spacing:-1.2px;margin:12px 0}
.post-page .post-body{font-size:16px;line-height:1.85;overflow-wrap:anywhere}
.post-page .post-body img{height:auto;max-width:100%}
.post-page .post-body h2,.post-page .post-body h3{line-height:1.3;margin-top:1.6em}
.post-page .post-body blockquote{margin:1.5em 0;padding:10px 20px;border-left:4px solid var(--accent);background:var(--soft)}
.post-page .post-body iframe{max-width:100%}
.post-cover{margin:20px 0}
.post-cover img{width:100%;height:auto;display:block}
.post-labels{display:flex;flex-wrap:wrap;gap:7px;margin:15px 0}
.post-labels a{font-size:11px;background:var(--soft);padding:4px 8px;border-radius:3px}
.blog-pager{display:flex;justify-content:space-between;gap:15px;padding:25px 0}
.blog-pager a{border:1px solid var(--line);padding:8px 12px;border-radius:3px}
.status-msg-wrap{margin:20px 0;padding:15px;background:var(--soft)}
.site-footer{background:var(--footer);color:#e5eaf2;padding:34px 0 15px}
.footer-grid{display:grid;grid-template-columns:1.45fr 1fr 1fr 1fr;gap:32px}
.footer-brand .brand{font-size:22px;margin-bottom:12px}
.footer-brand p{font-size:11px;line-height:1.7;color:#c3cbd8;margin:0 0 12px}
.footer-col h2{font-size:13px;color:#fff;margin:2px 0 12px}
.footer-col ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:7px}
.footer-col a{font-size:11px;color:#c6cfdd}
.footer-col a:hover{color:var(--accent)}
.social-links{display:flex;flex-wrap:wrap;gap:9px}
.social-links a{display:grid;place-items:center;border:1px solid #48546a;width:31px;height:31px;border-radius:50%;font-size:12px;font-weight:700}
.footer-bottom{border-top:1px solid #354158;margin-top:25px;padding-top:13px;display:flex;justify-content:space-between;gap:15px;color:#aeb9ca;font-size:10px}
.back-top{position:fixed;right:17px;bottom:17px;z-index:800;width:38px;height:38px;border:0;border-radius:3px;background:#05080e;color:#fff;cursor:pointer;opacity:0;visibility:hidden;transform:translateY(8px);transition:all .2s}
.back-top.is-visible{opacity:1;visibility:visible;transform:none}
.reveal-ready .reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s cubic-bezier(.2,.7,.2,1)}
.reveal-ready .reveal.is-revealed{opacity:1;transform:none}
@keyframes dropIn{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.reveal-ready .reveal{opacity:1;transform:none}}
@media(min-width:1100px){.home-layout{gap:46px}}
@media(max-width:1000px){.header-inner{gap:14px}.primary-nav{gap:13px}.primary-nav a{font-size:11px}.home-layout{grid-template-columns:minmax(0,1.7fr) minmax(245px,1fr);gap:26px}.featured-layout{gap:15px}.mini-article{grid-template-columns:86px minmax(0,1fr)}.sidebar-list .mini-article{grid-template-columns:82px minmax(0,1fr)}.footer-grid{gap:22px}}
@media(max-width:780px){.wrap{width:min(100% - 30px,var(--container))}.header-inner{min-height:60px}.brand{font-size:20px}.menu-toggle{display:grid}.primary-nav{display:none;position:absolute;left:0;right:0;top:100%;margin:0;padding:10px 20px 18px;background:var(--brand-deep);align-items:stretch;gap:0;box-shadow:0 12px 18px rgba(0,0,0,.14)}.primary-nav.is-open{display:flex;flex-direction:column;animation:dropIn .22s ease both}.primary-nav a{font-size:13px;padding:11px 3px;border-bottom:1px solid rgba(255,255,255,.1)}.primary-nav .coop-link{display:inline-block;align-self:flex-start;margin-top:10px;padding:8px 15px;border:0}.header-actions{margin-left:auto}.home-layout{grid-template-columns:minmax(0,1fr);gap:32px}.business-sidebar{border-top:1px solid var(--line);padding-top:22px}.sidebar-list{display:grid;grid-template-columns:1fr 1fr;gap:15px}.sidebar-list .mini-article{grid-template-columns:88px minmax(0,1fr)}.featured-layout{grid-template-columns:1.05fr .95fr}.footer-grid{grid-template-columns:1fr 1fr}.footer-brand{grid-column:1/-1}.footer-bottom{flex-direction:column;gap:5px}}
@media(max-width:520px){.page-shell{padding-top:22px}.section-heading h2,.section-heading h1{font-size:17px}.featured-layout{grid-template-columns:minmax(0,1fr);gap:18px}.featured-primary .thumb{aspect-ratio:16/9}.featured-primary .article-title{font-size:19px}.featured-list{display:grid;grid-template-columns:1fr 1fr;gap:13px}.featured-list .mini-article{grid-template-columns:minmax(0,1fr);gap:7px}.featured-list .mini-article .mini-thumb{aspect-ratio:4/3}.featured-list .mini-article h3{font-size:11px}.featured-secondary-grid{grid-template-columns:1fr}.featured-secondary .mini-article{grid-template-columns:95px minmax(0,1fr)}.category-row{grid-template-columns:minmax(0,1fr);gap:25px}.category-list{display:grid;grid-template-columns:1fr 1fr;gap:13px}.category-list .mini-article{grid-template-columns:minmax(0,1fr);gap:7px}.category-list .mini-article .mini-thumb{aspect-ratio:4/3}.category-list .mini-article h3{font-size:11px}.latest-grid{gap:22px 13px}.article-card .article-title{font-size:13px}.article-card .post-excerpt{display:none}.sidebar-list{grid-template-columns:minmax(0,1fr)}.sidebar-list .mini-article{grid-template-columns:100px minmax(0,1fr)}.footer-grid{gap:23px 15px}.footer-col h2{font-size:12px}.footer-brand p{max-width:390px}}

body.script:
//
(function(){
  'use strict';
  var header=document.getElementById('site-header');
  var searchToggle=document.getElementById('search-toggle');
  var searchPanel=document.getElementById('search-panel');
  var menuToggle=document.getElementById('menu-toggle');
  var nav=document.getElementById('primary-nav');
  var backTop=document.getElementById('back-top');
  var reduced=window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function onScroll(){
    var scrolled=window.pageYOffset>12;
    if(header) header.classList.toggle('is-scrolled',scrolled);
    if(backTop) backTop.classList.toggle('is-visible',window.pageYOffset>420);
  }
  window.addEventListener('scroll',onScroll,{passive:true}); onScroll();

  if(searchToggle && searchPanel){
    searchToggle.addEventListener('click',function(){
      var open=searchPanel.classList.toggle('is-open');
      searchToggle.setAttribute('aria-expanded',String(open));
      if(open){var input=searchPanel.querySelector('input');if(input)input.focus();}
    });
  }
  if(menuToggle && nav){
    menuToggle.addEventListener('click',function(){
      var open=nav.classList.toggle('is-open');
      menuToggle.setAttribute('aria-expanded',String(open));
    });
    nav.addEventListener('click',function(e){
      if(e.target && e.target.closest('a')){nav.classList.remove('is-open');menuToggle.setAttribute('aria-expanded','false');}
    });
    document.addEventListener('keydown',function(e){
      if(e.key==='Escape'){nav.classList.remove('is-open');menuToggle.setAttribute('aria-expanded','false');if(searchPanel)searchPanel.classList.remove('is-open');}
    });
  }
  if(backTop) backTop.addEventListener('click',function(){window.scrollTo({top:0,behavior:reduced?'auto':'smooth'});});

  // Progressive reveal: content stays visible if IntersectionObserver is unavailable.
  if(!reduced && 'IntersectionObserver' in window){
    document.documentElement.classList.add('reveal-ready');
    var observer=new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){entry.target.classList.add('is-revealed');observer.unobserve(entry.target);}
      });
    },{threshold:.08,rootMargin:'0px 0px -30px 0px'});
    document.querySelectorAll('.reveal').forEach(function(el){observer.observe(el);});
  }

  // Blogger JSON feed: fills label-based category cards and business sidebar.
  // If a feed is unavailable, the page still remains usable.
  function cleanText(html){
    var div=document.createElement('div');div.innerHTML=html||'';
    return (div.textContent||div.innerText||'').replace(/\s+/g,' ').trim();
  }
  function getImage(entry){
    if(entry.media$thumbnail && entry.media$thumbnail.url){
      return entry.media$thumbnail.url.replace(/\/s\d+(-c)?\//,'/s640/');
    }
    var html=(entry.content&&entry.content.$t)||(entry.summary&&entry.summary.$t)||'';
    var match=html.match(/<img[^>]+src=["']([^"']+)["']/i);
    return match?match[1]:'';
  }
  function getUrl(entry){
    var links=entry.link||[];
    for(var i=0;i<links.length;i++){if(links[i].rel==='alternate')return links[i].href;}
    return '#';
  }
  function card(entry){
    var url=getUrl(entry), title=cleanText(entry.title&&entry.title.$t)||'Read article';
    var img=getImage(entry), summary=cleanText(entry.summary&&entry.summary.$t||entry.content&&entry.content.$t).slice(0,125);
    var article=document.createElement('article');article.className='mini-article';
    var a=document.createElement('a');a.className='mini-thumb';a.href=url;a.setAttribute('aria-label',title);
    if(img){var image=document.createElement('img');image.src=img;image.alt=title;image.loading='lazy';image.width=260;image.height=195;a.appendChild(image);}
    var text=document.createElement('div'), h=document.createElement('h3'), link=document.createElement('a');
    link.href=url;link.textContent=title;h.appendChild(link);text.appendChild(h);
    if(summary){var p=document.createElement('p');p.className='post-excerpt';p.textContent=summary; text.appendChild(p);}
    article.appendChild(a);article.appendChild(text);return article;
  }
  function loadLabelFeed(el){
    var label=el.getAttribute('data-label'), count=parseInt(el.getAttribute('data-count')||'4',10);
    if(!label)return;
    var url='/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json&max-results='+Math.min(Math.max(count,1),10);
    fetch(url,{credentials:'same-origin'}).then(function(response){if(!response.ok)throw new Error('Feed unavailable');return response.json();}).then(function(data){
      var entries=data&&data.feed&&data.feed.entry||[];
      el.textContent='';
      if(!entries.length){var empty=document.createElement('p');empty.className='post-excerpt';empty.textContent='No posts found for the '+label+' label yet.';el.appendChild(empty);return;}
      entries.forEach(function(entry){el.appendChild(card(entry));});
    }).catch(function(){
      el.textContent='';
      var fallback=document.createElement('p');fallback.className='post-excerpt';fallback.textContent='Add posts with the "'+label+'" label to show articles here.';el.appendChild(fallback);
    });
  }
  document.querySelectorAll('[data-label][data-count]').forEach(loadLabelFeed);
})();
//
